package com.company.platform.inventory.application;
import com.company.platform.inventory.domain.*;import com.company.platform.inventory.infrastructure.*;import java.math.BigDecimal;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class InventoryService {private final TenantContextProvider tenant;private final InventoryStore store;private final ReservationStore reservations;private final InventoryEventPublisher events;public InventoryService(TenantContextProvider t,InventoryStore s,ReservationStore r,InventoryEventPublisher e){tenant=t;store=s;reservations=r;events=e;}private UUID t(){return tenant.currentTenantId();}public Inventory get(UUID id){return store.findInventory(t(),id).orElseThrow(()->new NoSuchElementException("INVENTORY_NOT_FOUND"));}public List<Inventory> list(){return store.findByProduct(t(),null);}public List<Inventory> byProduct(UUID p){return store.findByProduct(t(),p);}@Transactional public Inventory adjust(UUID id,BigDecimal amount){Inventory i=get(id);i.adjust(amount);Inventory saved=store.save(i);events.publish("INVENTORY_ADJUSTED",i.tenantId(),i.id(),i);return saved;}@Transactional public Inventory reserve(UUID id,BigDecimal quantity){if(quantity==null||quantity.signum()<=0)throw new IllegalArgumentException("INVALID_QUANTITY");get(id);if(!reservations.reserveStock(t(),id,quantity))throw new IllegalStateException("INSUFFICIENT_STOCK");return get(id);}@Transactional public Inventory release(UUID id,BigDecimal quantity){if(!reservations.releaseStock(t(),id,quantity))throw new IllegalStateException("INVALID_RESERVATION");return get(id);}@Transactional public Inventory consumeReserved(UUID id,BigDecimal quantity){if(!reservations.consumeStock(t(),id,quantity))throw new IllegalStateException("INVALID_RESERVATION");return get(id);}@Transactional public Inventory create(UUID productId,UUID locationId){Inventory i=store.save(Inventory.create(t(),productId,locationId));events.publish("INVENTORY_CREATED",i.tenantId(),i.id(),i);return i;}
 @Transactional public ReservationStore.ReservationRecord reserveProduct(UUID productId,UUID orderId,BigDecimal quantity,String reference){return reserveProductForTenant(t(),productId,orderId,quantity,reference);}@Transactional public ReservationStore.ReservationRecord reserveProductForTenant(UUID tenantId,UUID productId,UUID orderId,BigDecimal quantity,String reference){if(productId==null||orderId==null||quantity==null||quantity.signum()<=0)throw new IllegalArgumentException("INVALID_RESERVATION");String ref=reference==null||reference.isBlank()?orderId+"-"+productId:reference;var existing=reservations.findByReference(tenantId,ref);if(existing.isPresent())return existing.get();var inventory=store.findByProduct(tenantId,productId).stream().findFirst().orElseThrow(()->new NoSuchElementException("INVENTORY_NOT_FOUND"));if(!reservations.reserveStock(tenantId,inventory.id(),quantity))throw new IllegalStateException("INSUFFICIENT_STOCK");Reservation r=Reservation.create(tenantId,orderId,ref,Instant.now().plusSeconds(1800));r.reserve();var saved=reservations.save(r,inventory.id(),quantity);events.publish("INVENTORY_RESERVED",tenantId,r.id(),Map.of("reservationId",r.id().toString(),"orderId",orderId.toString(),"productId",productId.toString(),"quantity",quantity));return saved;}
 public List<ReservationStore.ReservationRecord> reservationsForOrder(UUID orderId){return reservations.findByOrder(t(),orderId);}public List<ReservationStore.ReservationRecord> reservationsForTenantOrder(UUID tenantId,UUID orderId){return reservations.findByOrder(tenantId,orderId);}public ReservationStore.ReservationRecord getReservation(UUID id){return reservations.find(t(),id).orElseThrow(()->new NoSuchElementException("RESERVATION_NOT_FOUND"));}
 @Transactional public ReservationStore.ReservationRecord consumeReservationForTenant(UUID tenantId,ReservationStore.ReservationRecord rec){if(rec.reservation().status()==ReservationStatus.CONSUMED)return rec;if(rec.reservation().status()!=ReservationStatus.RESERVED&&rec.reservation().status()!=ReservationStatus.ALLOCATED)throw new IllegalStateException("INVALID_RESERVATION_STATE");if(!reservations.consumeStock(tenantId,rec.inventoryId(),rec.quantity()))throw new IllegalStateException("INVALID_RESERVATION");rec.reservation().consume();var saved=reservations.save(rec.reservation(),rec.inventoryId(),rec.quantity());events.publish("INVENTORY_CONSUMED",tenantId,rec.reservation().id(),Map.of("reservationId",rec.reservation().id().toString()));return saved;}
 @Transactional public ReservationStore.ReservationRecord releaseReservation(UUID id){var rec=getReservation(id);if(rec.reservation().status()==ReservationStatus.RELEASED)return rec;if(rec.reservation().status()!=ReservationStatus.RESERVED&&rec.reservation().status()!=ReservationStatus.ALLOCATED)throw new IllegalStateException("INVALID_RESERVATION_STATE");if(!reservations.releaseStock(t(),rec.inventoryId(),rec.quantity()))throw new IllegalStateException("INVALID_RESERVATION");rec.reservation().release();var saved=reservations.save(rec.reservation(),rec.inventoryId(),rec.quantity());events.publish("INVENTORY_RELEASED",t(),id,Map.of("reservationId",id.toString()));return saved;}
 @Transactional public ReservationStore.ReservationRecord consumeReservation(UUID id){var rec=getReservation(id);if(rec.reservation().status()==ReservationStatus.CONSUMED)return rec;if(rec.reservation().status()!=ReservationStatus.RESERVED&&rec.reservation().status()!=ReservationStatus.ALLOCATED)throw new IllegalStateException("INVALID_RESERVATION_STATE");if(!reservations.consumeStock(t(),rec.inventoryId(),rec.quantity()))throw new IllegalStateException("INVALID_RESERVATION");rec.reservation().consume();var saved=reservations.save(rec.reservation(),rec.inventoryId(),rec.quantity());events.publish("INVENTORY_CONSUMED",t(),id,Map.of("reservationId",id.toString()));return saved;}
}
